import{_ as e,o as r,c as l,a2 as t}from"./chunks/framework.DV9MvnYb.js";const c=JSON.parse('{"title":"关于","description":"关于 VSVnakers 与这个网站","frontmatter":{"title":"关于","description":"关于 VSVnakers 与这个网站","sidebar":false,"aside":false},"headers":[],"relativePath":"resume/index.md","filePath":"resume/index.md","lastUpdated":1787408649000}'),i={name:"resume/index.md"};function s(o,a,n,h,u,d){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h1><p>你好，我是 <strong>VSVnakers</strong>。</p><p>我目前把主要精力放在系统编程相关方向：Rust、操作系统、计算机组成和 Linux 内核。这里是我的公开学习空间，用来保存长期有效的笔记、文章和资料索引。</p><h2 id="我在关注什么" tabindex="-1">我在关注什么 <a class="header-anchor" href="#我在关注什么" aria-label="Permalink to &quot;我在关注什么&quot;">​</a></h2><ul><li><strong>Rust</strong>：所有权模型、工程实践，以及它在系统软件中的使用方式；</li><li><strong>操作系统</strong>：进程与调度、虚拟内存、文件系统和并发；</li><li><strong>计算机系统</strong>：从指令执行、异常处理到软硬件接口；</li><li><strong>Linux 内核</strong>：沿真实调用路径理解成熟内核的实现与取舍。</li></ul><p>这些是当前学习方向，不是“已经精通”的技能清单。网站会保留探索过程中的修改与修正。</p><h2 id="为什么维护这个网站" tabindex="-1">为什么维护这个网站 <a class="header-anchor" href="#为什么维护这个网站" aria-label="Permalink to &quot;为什么维护这个网站&quot;">​</a></h2><p>我相信写作是检验理解的一种方式。一个概念只有在能够解释前提、过程和边界时，才算真正开始掌握。</p><p>因此，这里的内容会尽量做到：</p><ul><li>从具体问题出发，而不是堆砌术语；</li><li>区分已经验证的结论与仍在探索的想法；</li><li>给出必要的上下文、资料来源和复现路径；</li><li>发现错误后直接修正，由 Git 保留历史。</li></ul><h2 id="从哪里开始" tabindex="-1">从哪里开始 <a class="header-anchor" href="#从哪里开始" aria-label="Permalink to &quot;从哪里开始&quot;">​</a></h2><ul><li>想了解网站本身，可以读<a href="/posts/2025-05-22-hello-blog">从第一篇文章开始</a>；</li><li>想看我的学习方向，可以读<a href="/posts/2026-08-12-systems-learning-map">系统学习地图</a>；</li><li>想快速浏览近期研究，可以进入<a href="/papers/">每日论文</a>；</li><li>想查资料，可以进入<a href="/study/">学习页面</a>；</li><li>有问题或建议，欢迎前往<a href="/guestbook/">留言板</a>。</li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><ul><li>GitHub：<a href="https://github.com/vsvnakers" target="_blank" rel="noreferrer">github.com/vsvnakers</a></li><li>Email：<a href="mailto:vsvnakers@outlook.com" target="_blank" rel="noreferrer">vsvnakers@outlook.com</a></li></ul><p>讨论文章错误、学习路线和系统编程问题都很欢迎。涉及具体问题时，如果能附上环境、现象和已经尝试过的方法，会更容易一起定位。</p>',15)])])}const m=e(i,[["render",s]]);export{c as __pageData,m as default};
